// Subscribe once, for example in the form constructor:
pnlHeader.Paint += pnlHeader_Paint;

private void pnlHeader_Paint(object sender, PaintEventArgs e)
{
    using (var pen = new Pen(Color.SteelBlue, 2))
    {
        e.Graphics.DrawLine(pen, 0, pnlHeader.Height - 1, pnlHeader.Width, pnlHeader.Height - 1);
    }
}

// Subscribe once, for example in the form constructor:
pnlHeader.Resize += pnlHeader_Resize;

private void pnlHeader_Resize(object sender, EventArgs e)
{
    lblTitle.Left = (pnlHeader.Width - lblTitle.Width) / 2;
}

// Subscribe once, for example in the form constructor:
pnlHeader.ControlAdded += pnlHeader_ControlAdded;

private void pnlHeader_ControlAdded(object sender, ControlEventArgs e)
{
    e.Control.Margin = new Padding(6);
}

// Subscribe once, for example in the form constructor:
grpOptions.Enter += grpOptions_Enter;

private void grpOptions_Enter(object sender, EventArgs e)
{
    grpOptions.ForeColor = Color.SteelBlue;
}

// Subscribe once, for example in the form constructor:
grpOptions.Paint += grpOptions_Paint;

private void grpOptions_Paint(object sender, PaintEventArgs e)
{
    e.Graphics.DrawRectangle(Pens.SteelBlue, 0, 0, grpOptions.Width - 1, grpOptions.Height - 1);
}

// Subscribe once, for example in the form constructor:
tabMain.SelectedIndexChanged += tabMain_SelectedIndexChanged;

private void tabMain_SelectedIndexChanged(object sender, EventArgs e)
{
    lblStatus.Text = "Page: " + tabMain.SelectedTab?.Text;
}

// Subscribe once, for example in the form constructor:
tabMain.Selecting += tabMain_Selecting;
// assumes a tab page named tabAdvanced and a bool field named isAdmin

private void tabMain_Selecting(object sender, TabControlCancelEventArgs e)
{
    if (e.TabPage == tabAdvanced && !isAdmin)
    {
        e.Cancel = true; // stay on the current tab
    }
}

// Subscribe once, for example in the form constructor:
tabMain.Selected += tabMain_Selected;

private void tabMain_Selected(object sender, TabControlEventArgs e)
{
    lblStatus.Text = "Now on " + e.TabPage.Text;
}

// Subscribe once, for example in the form constructor:
tabMain.Deselecting += tabMain_Deselecting;

private void tabMain_Deselecting(object sender, TabControlCancelEventArgs e)
{
    if (!ValidateChildren())
    {
        e.Cancel = true;
    }
}

// Subscribe once, for example in the form constructor:
tabGeneral.Enter += tabGeneral_Enter;

private void tabGeneral_Enter(object sender, EventArgs e)
{
    txtName.Focus();
}

// Subscribe once, for example in the form constructor:
tabGeneral.Leave += tabGeneral_Leave;

private void tabGeneral_Leave(object sender, EventArgs e)
{
    lblStatus.Text = "Left the General page";
}

// Subscribe once, for example in the form constructor:
splitMain.SplitterMoved += splitMain_SplitterMoved;

private void splitMain_SplitterMoved(object sender, SplitterEventArgs e)
{
    lblInfo.Text = "Left panel width: " + splitMain.SplitterDistance;
}

// Subscribe once, for example in the form constructor:
splitMain.SplitterMoving += splitMain_SplitterMoving;

private void splitMain_SplitterMoving(object sender, SplitterCancelEventArgs e)
{
    if (e.SplitX < 150)
    {
        e.Cancel = true; // keep the left panel at least 150 pixels wide
    }
}

// Subscribe once, for example in the form constructor:
flowButtons.ControlAdded += flowButtons_ControlAdded;

private void flowButtons_ControlAdded(object sender, ControlEventArgs e)
{
    e.Control.Margin = new Padding(6);
}

// Subscribe once, for example in the form constructor:
flowButtons.ControlRemoved += flowButtons_ControlRemoved;

private void flowButtons_ControlRemoved(object sender, ControlEventArgs e)
{
    lblCount.Text = flowButtons.Controls.Count + " items";
}

// Subscribe once, for example in the form constructor:
tblLayout.CellPaint += tblLayout_CellPaint;

private void tblLayout_CellPaint(object sender, TableLayoutCellPaintEventArgs e)
{
    if (e.Row == 0)
    {
        using (var brush = new SolidBrush(Color.LightSteelBlue))
        {
            e.Graphics.FillRectangle(brush, e.CellBounds);
        }
    }
}
